'use strict';
// Synthetic standalone preview. Serves only this fixture and its UI module.
const http=require('node:http'),fs=require('node:fs'),path=require('node:path'),{createLaborGuard,child,parts,put}=require('../../cotizador/labor-guard'),{createOTOfficeCount}=require('../../cotizador/ot-office-count');
function start(port=0){
 let data={sv_labor_config:{schema:1,ready:true,otOfficeCountVersion:1},sv_chat_roles:{demo:{activo:true,rol:'administrativo'}},sv_chat_directorio:{demo:{nombre:'Persona de prueba'}},sv_permisos:{administrativo:{indiceVersion:2,indiceRevision:1,indiceModulos:{ordentrabajo:true},acciones:{ot:{ajustarStockOficina:true}}}},sisventas:{ordenes_trabajo:{demo:{id:'OT-EJEMPLO',ventaFbKey:'venta-ejemplo',estado:'en_curso',materiales:[{productoKey:'balun',cod:'P-EJEMPLO-1',desc:'Balun de ejemplo',adicionalOT:true,custodiaActiva:true,entregada:2,instalada:2,stockBaseInstalada:0,stockPendiente:true},{productoKey:'fuente',cod:'P-EJEMPLO-2',desc:'Fuente de ejemplo',adicionalOT:true,custodiaActiva:true,entregada:1,instalada:1,stockBaseInstalada:0,stockPendiente:true}]}},inventario_operativo:{balun:{general:0,consumido:0,reservado:0},fuente:{general:0,consumido:0,reservado:0}},productos:{balun:{codigo:'P-EJEMPLO-1',nombre:'Balun de ejemplo',unidad:'Unidad'},fuente:{codigo:'P-EJEMPLO-2',nombre:'Fuente de ejemplo',unidad:'Unidad'}}}};
 const read=async p=>child(data,parts(p)),store={read,readAsUser:read,query:async()=>({}),acquire:async lease=>{data.sv_labor_guard=lease;},abort:async()=>{delete data.sv_labor_guard;},commit:async patch=>{for(const [p,v]of Object.entries(patch))data=put(data,parts(p),v);}};
 const guard=createLaborGuard({store}),db={ref:p=>({get:async()=>({val:()=>child(data,parts(p))})})},api=createOTOfficeCount({db,store,guard,enabled:true});
 const html=()=>`<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ejemplo de stock desde OT</title><style>:root{--bg2:#101b2d;--text:#edf3fc;--text2:#afbdd1;--border:#2c3d57;--border2:#405473}*{box-sizing:border-box}body{margin:0;background:#080f1b;color:var(--text);font:14px system-ui;padding:24px}.btn,.search-input{background:#1a2b45;color:var(--text);border:1px solid var(--border2);border-radius:8px;padding:10px 14px;font:inherit}.btn{cursor:pointer}.btn:disabled{opacity:.55;cursor:default}.btn-primary{background:#ecf4ff;color:#101a2b}.card{max-width:950px;margin:auto;border:1px solid var(--border);border-radius:16px;padding:24px}.row{padding:16px 0;border-top:1px solid var(--border);display:flex;gap:16px;align-items:center;justify-content:space-between;flex-wrap:wrap}.muted{color:var(--text2);font-size:12px}.notice{color:#f1ce71;margin:0 0 22px}.badge{display:inline-block;background:#263a53;padding:3px 8px;border-radius:20px}.b-amber{color:#f1ce71}.b-green{color:#86d895}button:focus-visible,input:focus-visible,textarea:focus-visible{outline:2px solid #91baff;outline-offset:3px}@media(max-width:520px){body{padding:12px}.card{padding:16px}}</style><div class="card"><p class="notice">Ejemplo con datos ficticios · No modifica SisVentas</p><h2>Materiales de OT de ejemplo</h2><p class="muted">Contá lo que queda en oficina después de la instalación. Podés probar cinco unidades de cada producto.</p><div id="rows"></div><p id="toast" role="status"></p></div><script>
const user={uid:'demo'};window.currentUserUid='demo';window.currentRole='administrativo';window.fbAuth={currentUser:user};window.fbDB={};window.permisoModulo=()=>true;window.tienePermiso=()=>true;window.otActualId='demo';window.otData=[${JSON.stringify({...data.sisventas.ordenes_trabajo.demo,fbKey:'demo'})}];window.prodData=${JSON.stringify(Object.fromEntries(Object.entries(data.sisventas.productos).map(([k,v])=>[k,{...v,fbKey:k}])))};window.SISVENTAS_FUNCTIONS={cotizadorProveedor:location.origin};window.SVServiceAuth={headers:async h=>h};window.fbRef=(_,p)=>p;window.fbGet=async p=>{const r=await fetch('/snapshot?path='+encodeURIComponent(p));if(!r.ok)throw Error('Lectura ficticia no disponible');const v=await r.json();return{val:()=>v}};window.notify=m=>document.getElementById('toast').textContent=m;window.otCustodiaRenderMateriales=render;function render(){document.getElementById('rows').innerHTML=otData[0].materiales.map((m,i)=>'<div class="row"><div><strong>'+m.desc+'</strong><p class="muted">'+m.cod+' · Usado: '+m.instalada+'</p><span class="badge '+(m.stockPendiente?'b-amber':'b-green')+'">'+(m.stockPendiente?'Stock pendiente':'Instalado · stock registrado')+'</span></div>'+SVOTOfficeCount.button(otData[0],m,i)+'</div>').join('')}
</script><script src="/module.js"></script><script>render()</script></html>`;
 const server=http.createServer(async(req,res)=>{try{const url=new URL(req.url,'http://localhost');res.setHeader('Cache-Control','no-store');if(req.method==='GET'&&url.pathname==='/'){res.setHeader('Content-Type','text/html; charset=utf-8');res.end(html());return;}if(req.method==='GET'&&url.pathname==='/module.js'){res.setHeader('Content-Type','text/javascript; charset=utf-8');res.end(fs.readFileSync(path.join(__dirname,'../../js/modules/ot-office-count.js')));return;}if(req.method==='GET'&&url.pathname==='/snapshot'){const p=url.searchParams.get('path');if(!/^sisventas\/(ordenes_trabajo\/demo|inventario_operativo\/(balun|fuente))$/.test(p))throw Error('Ruta de ejemplo no permitida');res.setHeader('Content-Type','application/json');res.end(JSON.stringify(await read(p)));return;}if(req.method==='POST'&&url.pathname==='/inventario/contar-desde-ot'){let raw='';for await(const chunk of req){raw+=chunk;if(raw.length>4096)throw Error('Solicitud demasiado grande');}const result=await api.execute({uid:'demo',claims:{uid:'demo'}},JSON.parse(raw));res.setHeader('Content-Type','application/json');res.end(JSON.stringify(result));return;}res.writeHead(404);res.end();}catch(e){res.writeHead(e.statusCode||500,{'Content-Type':'application/json'});res.end(JSON.stringify({ok:false,mensaje:e.message}));}});
 return new Promise(resolve=>server.listen(port,'127.0.0.1',()=>resolve({server,url:'http://127.0.0.1:'+server.address().port,getData:()=>structuredClone(data)})));
}
if(require.main===module)start(Number(process.argv[2])||8895).then(s=>console.log('Ejemplo ficticio: '+s.url));
module.exports={start};
